@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .

@prefix geojson: <https://purl.org/geojson/vocab#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <file:///github/workspace/0> ;
            sh:resultMessage "Value does not conform to Shape geojson:GeometryShape" ;
            sh:resultPath geojson:geometry ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:NodeConstraintComponent ;
            sh:sourceShape [ sh:description "A Feature may have at most one geometry value; null geometry produces no RDF triple." ;
                    sh:maxCount 1 ;
                    sh:name "geometry" ;
                    sh:node geojson:GeometryShape ;
                    sh:nodeKind sh:BlankNodeOrIRI ;
                    sh:path geojson:geometry ] ;
            sh:value [ a geojson:MultiPolygon ;
                    geojson:coordinates () ] ] .
